import {today,isDate,shiftDate,statuses,csv,yearLabel} from './model.mjs';
import {attendanceCategory} from './attendance-overview.mjs';
import {activeTimetableInfo} from './teaching-data.mjs';
const codes={'Not Taken':'—',Present:'P','Internal Inclusion':'II','Absent (Excused)':'AE','Absent (Unexcused)':'AU','Late (Excused)':'LE','Late (Unexcused)':'LU','Left Early (Excused)':'EE','Left Early (Unexcused)':'EU'};
export function createAttendanceOverviewUI(ui){
 const {esc,options,button}=ui,$=s=>document.querySelector(s);let data=null,pending=null,error='',dateKey='',visible=[],request=0;
 const href=(tab,date)=>'#/attendance?'+new URLSearchParams({tab,date});
 function chip(status,text=status,title=''){return `<span class="attendance-code ${attendanceCategory(status)}" title="${esc(title||status)}">${esc(text)}</span>`;}
 function link(e,date){const content=chip(e.status,codes[e.status],e.className+' · '+e.status+(e.time?' at '+e.time:''));return e.canOpen?`<a href="#/attendance?${new URLSearchParams({class:e.classId,period:e.period,date})}" aria-label="${esc(e.className+' period '+e.period+': '+e.status)}">${content}</a>`:`<a href="#/directory-class?id=${e.classId}" title="${esc(e.className)}">${content}</a>`;}
 function fetchData(date,refresh=false){if(!refresh&&dateKey===date&&(data||pending||error))return;dateKey=date;data=null;error='';const id=++request;pending=fetch('/api/attendance/overview?date='+date,{credentials:'same-origin',cache:'no-store'}).then(async r=>{const d=await r.json();if(!r.ok)throw Error(d.error);if(id===request)data=d;}).catch(e=>{if(id===request)error=e.message;}).finally(()=>{if(id===request){pending=null;if(ui.route().path==='/attendance'&&!ui.route().params.get('class')&&ui.canRender())ui.render();}});}
 function refreshVisible(){if(dateKey&&!pending&&!document.hidden&&ui.route().path==='/attendance'&&!ui.route().params.get('class')&&ui.canRender())fetchData(dateKey,true);}
 setInterval(refreshVisible,30000);window.addEventListener('focus',refreshVisible);
 function page(params){const date=isDate(params.get('date')||'')?params.get('date'):(activeTimetableInfo()?.testDate||today()),tab=['all','school','class'].includes(params.get('tab'))?params.get('tab'):'all';fetchData(date);setTimeout(()=>{if(data&&ui.route().path==='/attendance'&&!ui.route().params.get('class'))paint();},0);return `<div class="attendance-overview-heading"><h1>Attendance</h1><div class="actions">${button('↻ Refresh','ao-refresh','','small')}${button('Export CSV','ao-export','','small')}</div></div><nav class="attendance-overview-tabs" aria-label="Attendance views">${[['all','View all'],['school','School attendance'],['class','Class attendance']].map(([id,label])=>`<a href="${href(id,date)}" ${id===tab?'class="active" aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="attendance-overview-toolbar">${button('‹','ao-date','data-days="-1" aria-label="Previous attendance day"','small')}<label class="sr-only" for="ao-date">Attendance date</label><input id="ao-date" type="date" value="${date}">${button('›','ao-date','data-days="1" aria-label="Next attendance day"','small')}<label class="sr-only" for="ao-search">Find student or class</label><input id="ao-search" type="search" placeholder="${tab==='class'?'Find class or teacher':'Find student'}" value="${esc(params.get('q')||'')}"><label class="sr-only" for="ao-year">Year</label><select id="ao-year">${options([['','All years'],['FS1','FS1'],['FS2','FS2'],...Array.from({length:13},(_,i)=>[String(i+1),'Year '+String(i+1).padStart(2,'0')])],params.get('year')||'')}</select></div><div id="ao-summary" class="attendance-overview-summary">${data?summary(tab):''}</div><div class="attendance-overview-filters">${tab==='class'?`<label>Period <select id="ao-period">${options([['','All periods'],...(['R','1','2','3','4','5','6','7','8'].map(p=>[p,p==='R'?'Registration':'Period '+p]))],params.get('period')||'')}</select></label><label>Status <select id="ao-completion">${options([['','All statuses'],['untaken','Not taken'],['incomplete','Incomplete'],['complete','Complete']],params.get('completion')||'')}</select></label>`:`<label>School <select id="ao-school">${options([['','All school attendance'],...statuses.map(s=>[s,s])],params.get('school')||'')}</select></label>${tab==='all'?`<label>Class <select id="ao-class-status">${options([['','All class attendance'],...statuses.map(s=>[s,s])],params.get('classStatus')||'')}</select></label><label><input id="ao-discrepancies" type="checkbox" ${params.get('discrepancies')==='true'?'checked':''}> Discrepancies only</label>`:''}`}</div><p class="attendance-overview-note">${data?esc(data.scope)+' · ':''}${tab==='class'?(activeTimetableInfo()?'Assigned weekly timetable plus all saved registers. Counts use saved marks only.':'Sample weekday timetable plus all saved registers. Counts use saved marks only.'):'Daily absence clears when any saved lesson confirms attendance. Original registration and lesson marks remain visible. Refreshes every 30 seconds; grey means not recorded.'}</p><section class="panel attendance-overview-results"><p id="ao-count" role="status">${error?esc(error):'Loading saved attendance…'}</p><div id="ao-table" class="table-wrap"></div></section>`;}
 function summary(tab){const t=tab==='class'?data.classTotals:data.totals;return Object.entries(t).map(([key,n])=>`<span class="attendance-total ${key}"><strong>${n}</strong> ${tab==='class'?({complete:'Classes complete',incomplete:'Classes incomplete',untaken:'Classes not taken'})[key]:({present:'Present',absent:'Absent',late:'Late',early:'Left early',untaken:'Not taken'})[key]}</span>`).join('');}
 function paint(){if(!data||!$('#ao-table'))return;const p=ui.route().params,tab=p.get('tab')||'all',q=($('#ao-search')?.value||'').toLowerCase(),year=$('#ao-year').value;$('#ao-summary').innerHTML=summary(tab);if(tab==='class'){const period=$('#ao-period').value,status=$('#ao-completion').value;visible=data.classes.filter(c=>(!q||(c.name+' '+c.teacher).toLowerCase().includes(q))&&(!year||String(c.year)===year)&&(!period||period===c.period)&&(!status||status===c.status));$('#ao-table').innerHTML=`<table class="data-table"><thead><tr><th>Period</th><th>Class</th><th>Teacher</th><th>Status</th><th>Absent</th><th>Late</th><th>Present</th><th>Left early</th><th>Not taken</th></tr></thead><tbody>${visible.map(c=>`<tr><td>${c.period==='R'?'Registration':c.period}</td><td><a href="${c.canOpen?'#/attendance?'+new URLSearchParams({class:c.classId,date:data.date,period:c.period}):'#/directory-class?id='+c.classId}">${esc(c.name)}</a>${!c.scheduled?'<small>Additional saved register</small>':''}</td><td><a href="#/person?id=${c.teacherId}">${esc(c.teacher)}</a></td><td><span class="attendance-code ${c.status}">${({complete:'Complete',incomplete:'Incomplete',untaken:'Not taken'})[c.status]}</span></td>${['absent','late','present','early','untaken'].map(k=>`<td>${c.counts[k]}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}else{const status=$('#ao-school').value,classStatus=$('#ao-class-status')?.value,discrepancy=$('#ao-discrepancies')?.checked;visible=data.pupils.filter(s=>(!q||s.name.toLowerCase().includes(q))&&(!year||String(s.year)===year)&&(!status||status===s.schoolStatus)&&(!classStatus||s.entries.some(e=>e.status===classStatus))&&(!discrepancy||s.discrepancy));$('#ao-table').innerHTML=`<table class="data-table"><thead><tr><th>Student</th><th>Year</th><th>School attendance</th>${tab==='all'?data.periods.map(([id])=>`<th>${id==='R'?'Reg':id}</th>`).join(''):''}</tr></thead><tbody>${visible.map(s=>`<tr><td><a href="#/person?id=${s.id}">${esc(s.name)}</a>${s.discrepancy?'<small class="attendance-discrepancy">Check absence / presence</small>':''}</td><td>${esc(yearLabel(s.year))} ${esc(s.form)}</td><td>${chip(s.schoolStatus,s.schoolStatus+(s.arrival?' · '+s.arrival:''))}${s.corrected?'<small>Attendance confirmed in period '+esc(s.arrivalPeriod)+'</small>':''}</td>${tab==='all'?data.periods.map(([id])=>`<td>${s.entries.filter(e=>e.period===id).map(e=>link(e,data.date)).join(' ')||chip('Not Taken','—','No saved mark for this period')}</td>`).join(''):''}</tr>`).join('')}</tbody></table>`;}$('#ao-count').textContent=visible.length+' matching '+(tab==='class'?'registers':'students')+(visible.length?'':' · No saved matches for these filters');}
 function update(){if(!$('#ao-date'))return;const p=ui.route().params;p.set('q',$('#ao-search').value);p.set('year',$('#ao-year').value);for(const [id,key] of [['ao-period','period'],['ao-completion','completion'],['ao-school','school'],['ao-class-status','classStatus']])if($('#'+id))p.set(key,$('#'+id).value);if($('#ao-discrepancies'))p.set('discrepancies',String($('#ao-discrepancies').checked));ui.replaceHash('#/attendance?'+p);paint();}
 function change(t){if(t.id==='ao-date'){if(isDate(t.value))ui.navigate(href(ui.route().params.get('tab')||'all',t.value));return;}if(t.id.startsWith('ao-'))update();}
 function action(a,el){if(a==='ao-refresh'){fetchData($('#ao-date').value,true);ui.render();return true;}if(a==='ao-date'){ui.navigate(href(ui.route().params.get('tab')||'all',shiftDate($('#ao-date').value,Number(el.dataset.days))));return true;}if(a==='ao-export'){if(!data)return true;const tab=ui.route().params.get('tab');const rows=tab==='class'?[['Date','Period','Class','Teacher','Status','Absent','Late','Present','Left early','Not taken'],...visible.map(c=>[data.date,c.period,c.name,c.teacher,c.status,...['absent','late','present','early','untaken'].map(k=>c.counts[k])])]:[['Date','Student ID','Student','Year','Form','School status','Arrival','Discrepancy','Saved class marks'],...visible.map(s=>[data.date,s.id,s.name,yearLabel(s.year),s.form,s.schoolStatus,s.arrival,s.discrepancy?'Yes':'No',s.entries.map(e=>`P${e.period} ${e.className}: ${e.status}${e.time?' at '+e.time:''}`).join('; ')])];ui.download('attendance-'+(tab||'all')+'-'+data.date+'.csv',csv(rows));return true;}return false;}
 return{page,action,change,invalidate:()=>{dateKey='';data=null;error='';request++;pending=null;},input:t=>{if(t.id==='ao-search')update();}};
}
